INSERT INTO `ds_lokasi` (`id_lokasi`, `id_user`, `nama_lokasi`, `luas_lokasi`, `dimensi_lokasi`, `lat_lokasi`, `long_lokasi`, `pic_lokasi`, `pic_lokasi_hp`, `deskripsi_lokasi`, `alamat_lokasi`, `gambar_lokasi`, `nama_lokasi_menu`) VALUES
(1, 1, 'Screenhouse Penyemaian', '720', '18 x 40', '-6.548674', '106.733094', 'Milta', '081256325554', 'Greenhouse berkapasitas 250.000 sampai 500.000 bibit. Green house ini telah didukung dengan NMC pro Climate. Sebuah alat yang digunakan untuk mengatur micro climate di dalam green house. Selain itu, green house ini dilengkapi dengan alat kontrol Netbeat yang berfungsi untuk mengontrol penyiraman dan fertigasi.', 'Nursery Green House, Agribusiness and Technology Park, Cikarawang, Dramaga, Bogor Barat, Kota Bogor', 'images/area/gh_semaian/gh_semaian.jpg', 'GH Penyemaian');
INSERT INTO `ds_tanaman` (`id_tanaman`, `id_lokasi`, `tanggal_semai`, `tanggal_panen`, `jenis_tanaman`, `varietas_tanaman`, `populasi`, `tipe_budidaya`, `tipe_irigasi`, `pic_budidaya`, `deskripsi_budidaya`, `gambar_budidaya`, `h_up`, `s_up`, `v_up`, `h_low`, `s_low`, `v_low`) VALUES
(1, 1, '2023-10-07', '2023-07-17', 'Cabai ', 'Rawit Merah', '1500', 'hidroponik substrat', 'fertigasi tetes', 'Apoy', 'Cabai rawit (Capsicum frutescens) adalah buah dan tumbuhan anggota genus Capsicum yang buahnya tumbuh menjulang menghadap ke atas. Warna buahnya hijau kecil sewaktu muda dan jika telah masak berwarna merah tua. ', '', 225, 255, 44, 0, 0, '0');
